"""Render the bounded basic lexicon and evidence gate as an offline review."""
import argparse
import json
from pathlib import Path

HTML='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SignBridge 基础词组精标与动作复核</title><link rel="stylesheet" href="review.css"><body><main><h1>基础词组精标与动作复核</h1><p id="summary"></p><aside><strong>训练未开始。</strong>只有同一源视频、片段、动作和标注版本两轮独立全项一致性验收通过，才可进入训练。已运行的空间与时序技术检查不等于两轮完整通过；缺失、疑问或差异都不算通过。</aside><nav><a href="README.md">详细说明</a><a href="基础词组库.csv">基础词组CSV</a><a href="foundation.sqlite" download>SQLite精标库</a><a href="report.json">覆盖与缺项</a><a href="reviews/index.html">用户确认的“你”</a></nav><section><h2>先从基础库开始</h2><div class="controls"><label>字、词或含义<input id="query" placeholder="我、你们、早上好、邮局……"></label><label>单位类型<select id="type"><option value="">全部基础单位</option><option value="word">词</option><option value="phrase">词组</option><option value="sentence">句子</option></select></label><label>类别<select id="category"><option value="">全部类别</option></select></label><label>动作证据<select id="motion"><option value="">全部</option><option value="clips">有实际参考片段</option><option value="gap">缺少独立参考片段</option></select></label><button id="reset">重置</button></div><p id="count" role="status"></p><div id="units" class="units"></div></section><section id="detail"><h2>选择条目查看来源</h2><p>每个字只是书写组件，不自动产生独立手势。每段原片与骨骼证据分别核对，不能只改标签复制动作。</p></section><section><h2>字、词、词组、句子的口径</h2><div class="grid"><article><h3>字</h3><p>记录书写字符与上下文；“我”可以同时是一个字和一个词。“学”出现在“学校”里，不证明它有独立动作。</p></article><article><h3>词与Gloss</h3><p>中文词义与来源Gloss分开存储。单字不必都是词，多字也不必都是词组；考试1/考试2等来源变体不去编号。</p></article><article><h3>词组与句子</h3><p>你好、早上好等固定表达可作为完整问候使用。本库分别记录表达构成与话语功能，不因能独立说出就推断新的词级动作边界。</p></article></div><p id="character-note"></p><label>查看单个汉字<input id="character" maxlength="2" placeholder="例如：我"></label><p id="character-result"></p></section><section><h2>原字幕修订与隔离</h2><p>本轮直接查看89份原片中间画面，修订栏目混入、漏字和错字；这不是对完整手势的专家认证。</p><div id="corrections"></div></section><section><h2>逐动作的检查状态</h2><p id="action-summary"></p><label>筛选动作问题<select id="action-filter"><option value="">全部片段</option><option value="incomplete">原生参数缺帧</option><option value="no-native">没有精确原生动作映射</option><option value="native">有原生动作对照</option></select></label><div id="actions"></div><button id="more-actions">再显示20段</button></section></main><script src="review-data.js"></script><script src="review.js"></script></body></html>'''
CSS='''*{box-sizing:border-box}body{margin:0;background:#f3f5ef;color:#203c32;font:17px/1.65 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:28px}h1{font-size:32px;line-height:1.3}h2{font-size:24px}h3{font-size:19px;margin:6px 0}aside{background:#fff0cb;border-left:5px solid #9b762d;padding:18px}nav{display:flex;gap:18px;flex-wrap:wrap;margin:20px 0}a{color:#176879;overflow-wrap:anywhere}section{padding:22px;background:#fff;margin:24px 0;border-radius:12px}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:end}label{display:grid;gap:5px}.controls label:first-child{flex:1;min-width:220px}input,select,button{font:inherit;color:inherit;border:1px solid #93aa9b;padding:9px;border-radius:6px;background:white}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #af7523}.units{display:flex;gap:8px;flex-wrap:wrap}.units button{background:#e5eddf}.units button[aria-pressed=true]{background:#285847;color:white}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}article{border-bottom:1px solid #d7dfd4;padding:14px 0}article p{margin:6px 0}.warning{background:#fff0d6;border-left:4px solid #b77c27;padding:12px}.badge{display:inline-block;background:#f8edd4;padding:3px 9px;border-radius:4px;margin-right:7px}small{color:#5a6a61}video{display:block;width:min(100%,1000px);max-height:700px;background:#202820;margin:14px 0}img{display:block;max-width:100%;height:auto}#character-result{overflow-wrap:anywhere;word-break:break-word}.metrics{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 ui-monospace,monospace}[hidden]{display:none!important}@media(max-width:600px){main{padding:15px}section{padding:16px}.grid{grid-template-columns:1fr}.controls>*{width:100%}h1{font-size:28px}}'''
JS='''const data=window.FOUNDATION;const $=s=>document.querySelector(s),unitMap=new Map(data.units.map(x=>[x.id,x])),actionMap=new Map(data.actions.map(x=>[x.id,x]));let current=null,actionLimit=20;const kinds={word:'词',phrase:'词组',sentence:'句子',word_candidate:'词候选'};function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x}function para(text,parent,cls){const p=el('p',text,cls);parent.append(p);return p}function button(text,parent,fn){const b=el('button',text);b.addEventListener('click',fn);parent.append(b);return b}function movie(path,parent,button,start){const old=parent.querySelector('video');if(old&&old.getAttribute('src')===path){old.pause();old.remove();return}document.querySelectorAll('video').forEach(v=>{v.pause();v.remove()});const v=el('video');v.controls=true;v.playsInline=true;v.preload='metadata';v.src=path;if(start!==undefined)v.addEventListener('loadedmetadata',()=>{v.currentTime=start},{once:true});v.addEventListener('error',()=>para('视频读取失败，请保留整个资料目录。',parent,'warning'),{once:true});parent.append(v)}function actionCard(a,parent){const c=el('article');c.dataset.actionId=a.id;para(a.id,c);para(`参考${a.frames}帧 · ${a.fps}fps · 训练门禁关闭`,c);button('播放原片',c,()=>movie(a.clip,c));if(data.comparisons[a.id])button('播放原片／旧骨骼对照',c,()=>movie(data.comparisons[a.id].video,c));else para('没有本页可播放的完整骨骼对照；原片正常播放不等于动作验收通过。',c,'warning');const m=a.native_comparison;if(m){para(m.missing_native_frames.length?`旧参数缺${m.missing_native_frames.length}帧，隔离，不补帧。`:'旧参数帧集合完整，手型/词界/表情等仍须一致性验收。',c,'warning')}else para('该片段没有精确对应的完整原生动作证据，不能借同词其他片段替代。',c,'warning');const details=el('details');details.append(el('summary','查看两轮门禁与数值证据'));details.append(el('pre',JSON.stringify({rounds:a.validation_rounds,gate:a.training_gate,source_metrics:a.source_metrics,native_metrics:m?{spatial:m.spatial_round1,temporal:m.temporal_round2}:null},null,2),'metrics'));c.append(details);parent.append(c)}function show(id){current=id;const u=unitMap.get(id),d=$('#detail');d.replaceChildren(el('h2',u.text+' · '+(kinds[u.unit_type]||u.unit_type)));d.dataset.unitId=id;para(u.meaning,d);para(u.category+' · 独立双轮通过0/2 · 不可开训',d,'badge');if(u.do_not_equate.length)para('不能混同：'+u.do_not_equate.join('；'),d);if(!u.action_ids.length)para('尚无可独立核对的参考片段：保留来源上下文和缺项，不制造动作。',d,'warning');for(const f of u.source_forms){const a=el('article');a.append(el('h3','课程来源 '+f.source_id));para(f.meaning,a);para(f.manual_form_note||'未给出完整手部说明',a);para(f.nonmanual_note||'没有核准的非手部语义标签',a);para('来源留疑：'+f.uncertainties.join('；'),a);const start=f.intervals[0].start;button('打开原课教学上下文',a,()=>movie('tutorial-sources/video/'+f.source_id+'.mp4',a,null,start));d.append(a)}for(const aid of u.action_ids)actionCard(actionMap.get(aid),d);if(u.ce_train_examples.length){const group=el('details');group.append(el('summary','CE-CSL原train语境（整句，不能据此自动切词）'));for(const s of u.ce_train_examples){const a=el('article');para(s.chinese,a);para(s.gloss_sequence,a);button('播放整句语境',a,()=>movie(s.video,a));group.append(a)}d.append(group)}filterUnits()}function filterUnits(){const q=$('#query').value.trim(),kind=$('#type').value,cat=$('#category').value,m=$('#motion').value;const list=data.units.filter(u=>(!q||u.text.includes(q)||u.meaning.includes(q))&&(!kind||u.unit_type===kind)&&(!cat||u.category===cat)&&(!m||m==='clips'&&u.action_ids.length||m==='gap'&&!u.action_ids.length));$('#units').replaceChildren();for(const u of list){const b=button(u.text+' · '+(kinds[u.unit_type]||u.unit_type),$('#units'),()=>show(u.id));b.setAttribute('aria-pressed',String(u.id===current));b.dataset.unitId=u.id}$('#count').textContent=`显示${list.length}个基础单位；有片段不等于动作已正确。`}function filterActions(){const key=$('#action-filter').value;const list=data.actions.filter(a=>!key||key==='incomplete'&&a.native_comparison&&a.native_comparison.missing_native_frames.length||key==='no-native'&&!a.native_comparison||key==='native'&&a.native_comparison);$('#actions').replaceChildren();for(const a of list.slice(0,actionLimit))actionCard(a,$('#actions'));$('#more-actions').hidden=list.length<=actionLimit;$('#action-summary').textContent=`匹配${list.length}段，显示${Math.min(actionLimit,list.length)}段；两轮全项通过0段。`;}$('#summary').textContent=`127个基础单位：${data.report.foundation_unit_types.word}词 / ${data.report.foundation_unit_types.phrase}词组 / ${data.report.foundation_unit_types.sentence}句子；283段参考片段、29438帧已做原始观测。`;for(const value of [...new Set(data.units.map(x=>x.category))]){const o=el('option',value);o.value=value;$('#category').append(o)}for(const x of ['#query','#type','#category','#motion'])$(x).addEventListener(x==='#query'?'input':'change',filterUnits);$('#reset').addEventListener('click',()=>{for(const x of ['#query','#type','#category','#motion'])$(x).value='';filterUnits()});$('#character-note').textContent=`${data.characters.length}个去重汉字组件，来自原始句子/标签，可能包含尚未修订的OCR字形；独立字动作推断为0。`;$('#character').addEventListener('input',()=>{const c=data.characters.find(x=>x.character===$('#character').value);$('#character-result').textContent=c?`${c.character}：书写组件。出现统计${JSON.stringify(c.counts_by_source_scope)}。这不是该字的动作数量或训练资格。`:'没有匹配的单个书写字符。'});for(const x of data.corrections.filter(x=>x.corrected_text!==x.raw_text).slice(0,14)){const a=el('article');a.append(el('h3',x.raw_text+' → '+(x.corrected_text||'章节/上下文，移出词库')));para(x.reason,a);$('#corrections').append(a)}$('#action-filter').addEventListener('change',()=>{actionLimit=20;filterActions()});$('#more-actions').addEventListener('click',()=>{actionLimit+=20;filterActions()});filterUnits();filterActions();document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause())});'''


def build(root):
    r=Path(root).resolve()
    def rows(p):return [json.loads(x) for x in (r/p).read_text().splitlines() if x.strip()]
    comparisons=json.loads((r/'validation/comparison-videos.json').read_text())['records'] if (r/'validation/comparison-videos.json').exists() else []
    data={'units':rows('foundation-units.jsonl'),'actions':rows('action-checks.jsonl'),'characters':rows('characters.jsonl'),'report':json.loads((r/'report.json').read_text()),
          'corrections':json.loads((r/'source-annotations/caption-visual-corrections.json').read_text())['records'],'comparisons':{x['id']:x for x in comparisons}}
    if (r/'index.html').exists():raise FileExistsError('New review directory required')
    for name,text in [('index.html',HTML),('review.css',CSS),('review.js',JS),('review-data.js','window.FOUNDATION='+json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')+';\n')]: (r/name).write_text(text)
    return {'units':len(data['units']),'actions':len(data['actions']),'comparisons':len(comparisons)}


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--library',type=Path,required=True);print(json.dumps(build(p.parse_args().library)))
